38	import org.springframework.samples.petclinic.mapper.PetMapper;
39	import org.springframework.samples.petclinic.mapper.VisitMapper;
40	import org.springframework.samples.petclinic.model.Owner;
41	import org.springframework.samples.petclinic.model.Pet;
42	import org.springframework.samples.petclinic.model.Visit;
43	import org.springframework.samples.petclinic.rest.api.OwnersApi;
44	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
45	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
46	import org.springframework.samples.petclinic.rest.dto.PetDto;
47	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
48	import org.springframework.samples.petclinic.rest.dto.VisitDto;
49	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
50	import org.springframework.samples.petclinic.service.ClinicService;
51	import org.springframework.security.access.prepost.PreAuthorize;
52	import org.springframework.web.bind.annotation.CrossOrigin;
53	import org.springframework.web.bind.annotation.RequestMapping;
54	import org.springframework.web.bind.annotation.RestController;
55	import org.springframework.web.context.request.RequestAttributes;
56	import org.springframework.web.context.request.RequestContextHolder;
57	import org.springframework.web.context.request.ServletRequestAttributes;
58	import org.springframework.web.util.UriComponentsBuilder;
59	
60	import jakarta.transaction.Transactional;
61	
62	/**
63	 * @author Vitaliy Fedoriv
64	 */
65	
66	@RestController
67	@CrossOrigin(exposedHeaders = "errors, content-type")
68	@RequestMapping("/api")
69	public class OwnerRestControllerV1 implements OwnersApi {
70	
71	    /** Dedicated audit logger; each successful owner create emits one line here. */
72	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
73	
74	    /** Dedicated notification logger; each successful owner create enqueues a welcome line here. */
75	    private static final Logger NOTIFY = LoggerFactory.getLogger("NOTIFY");
76	
77	    /**
78	     * Monotonically increasing sequence stamped onto each structured {@code OWNER_CREATED}
79	     * event, shared across every controller instance so the {@code seq} strictly increases
80	     * across all owner creates for the life of the process.
81	     */
82	    private static final java.util.concurrent.atomic.AtomicLong AUDIT_EVENT_SEQ =
83	        new java.util.concurrent.atomic.AtomicLong();
84	
85	    /**
86	     * The header carrying an idempotency key for owner creation. When a create repeats with a key
87	     * already seen, the originally created owner is returned with 200 instead of creating a duplicate.
88	     */
89	    private static final String IDEMPOTENCY_KEY_HEADER = "Idempotency-Key";
90	
91	    /**
92	     * Remembers, per seen idempotency key, the id of the owner that create originally produced, so a
93	     * repeat of the same request returns that owner rather than creating a duplicate.
94	     */
95	    private final Map<String, Integer> idempotentCreates = new java.util.concurrent.ConcurrentHashMap<>();
96	
97	    private final ClinicService clinicService;
98	
99	    private final OwnerMapper ownerMapper;
100	
101	    private final PetMapper petMapper;
102	
103	    private final VisitMapper visitMapper;
104	
105	    public OwnerRestControllerV1(ClinicService clinicService,
106	                                 OwnerMapper ownerMapper,
107	                                 PetMapper petMapper,
108	                                 VisitMapper visitMapper) {
109	        this.clinicService = clinicService;
110	        this.ownerMapper = ownerMapper;
111	        this.petMapper = petMapper;
112	        this.visitMapper = visitMapper;
113	    }
114	
115	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
116	    @Override
117	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
118	        Collection<Owner> owners;
119	        if (lastName != null) {
120	            owners = this.clinicService.findOwnerByLastName(lastName);
121	        } else {
122	            owners = this.clinicService.findAllOwners();
123	        }
124	        if (owners.isEmpty()) {
125	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
126	        }
127	        Map<String, Integer> householdSizes = householdSizes();
128	        List<OwnerDto> ownerDtos = new java.util.ArrayList<>();
129	        for (Owner owner : owners) {
130	            OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
131	            applyMembership(ownerDto, owner, householdSizes);
132	            ownerDtos.add(ownerDto);
133	        }
134	        return new ResponseEntity<>(ownerDtos, HttpStatus.OK);
135	    }
136	
137	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
138	    @Override
139	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
140	        Owner owner = this.clinicService.findOwnerById(ownerId);
141	        if (owner == null) {
142	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
143	        }
144	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
145	        applyMembership(ownerDto, owner);
146	        ownerDto.setBulkSignupWarning(isBulkSignupDay());
147	        ownerDto.setCapacityWarning(isApproachingCapacity(owner.getCity()));
148	        return new ResponseEntity<>(ownerDto, HttpStatus.OK);
149	    }
150	
151	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
152	    @Override
153	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
154	        HttpHeaders headers = new HttpHeaders();
155	        String idempotencyKey = currentIdempotencyKey();
156	        if (idempotencyKey != null) {
157	            Integer existingId = idempotentCreates.get(idempotencyKey);
158	            if (existingId != null) {
159	                Owner existing = this.clinicService.findOwnerById(existingId);
160	                if (existing != null) {
161	                    OwnerDto existingDto = ownerMapper.toOwnerDto(existing);
162	                    applyMembership(existingDto, existing);
163	                    existingDto.setBulkSignupWarning(isBulkSignupDay());
164	                    existingDto.setCapacityWarning(isApproachingCapacity(existing.getCity()));
165	                    return new ResponseEntity<>(existingDto, HttpStatus.OK);
166	                }
167	            }
168	        }
169	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
170	        String address = applyAddress(owner, ownerFieldsDto);
171	        if (address.isEmpty()) {
172	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
173	        }
174	        owner.setAddress(address);
175	        String telephone = toE164(owner.getTelephone());
176	        if (telephone == null) {
177	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
178	        }
179	        owner.setTelephone(telephone);
180	        if (owner.getEmail() != null) {
181	            String email = normalizeEmail(owner.getEmail());
182	            if (email == null) {
183	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
184	            }
185	            owner.setEmail(email);
186	        }
187	        if (owner.getPostcode() != null && !isValidPostcode(owner.getPostcode(), owner.getCity())) {
188	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
189	        }
190	        LocalDate effectiveRegistrationDate = owner.getRegistrationDate();
191	        if (effectiveRegistrationDate == null) {
192	            effectiveRegistrationDate = LocalDate.now();
193	        }
194	        else if (effectiveRegistrationDate.isAfter(LocalDate.now())) {
195	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
196	        }
197	        LocalDate registrationDate = toBusinessDay(effectiveRegistrationDate);
198	        owner.setRegistrationDate(registrationDate);
199	        if (countOwnersInCity(owner.getCity()) >= MAX_OWNERS_PER_CITY) {
200	            return new ResponseEntity<>(HttpStatus.CONFLICT);
201	        }
202	        if (countOwnersRegisteredOn(registrationDate) >= MAX_OWNERS_PER_DAY) {
203	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
204	        }
205	        // The householdId is deterministic: the first twelve hex characters of SHA-256 over
206	        // '<normalizedLastName>|<postcode>'. Owners sharing a last name and postcode therefore
207	        // share the household automatically. An owner without a postcode has no household.
208	        boolean declaredHouseholdMember = false;
209	        if (owner.getPostcode() != null) {
210	            String householdId = householdId(householdKey(owner.getLastName()), owner.getPostcode());
211	            owner.setHouseholdId(householdId);
212	            // A second owner sharing a household (same lastName + postcode) but with a distinct
213	            // identity is a legitimate additional household member — true duplicates are still
214	            // caught by the identityKey check below. 'sharesHousehold' opts such an owner in as a
215	            // declared member so it is not additionally flagged as a possible duplicate.
216	            boolean householdOccupied = false;
217	            for (Owner existing : this.clinicService.findAllOwners()) {
218	                if (existing.isDeleted()) {
219	                    continue;
220	                }
221	                if (householdId.equals(computeHouseholdId(existing))) {
222	                    householdOccupied = true;
223	                    break;
224	                }
225	            }
226	            if (householdOccupied && Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
227	                declaredHouseholdMember = true;
228	            }
229	        }
230	        // Consolidated duplicate detection: reject only when the whole identityKey
231	        // (SHA-256 over normalizedTelephone | lowerEmail | soundex(lastName)) matches an
232	        // existing owner's. This is the single duplicate check; owners sharing a household
233	        // (same last name and postcode) but with different telephones produce different keys
234	        // and are no longer rejected here — they surface as soft matches below.
235	        String identityKey = OwnerIdentity.identityKey(owner.getTelephone(), owner.getEmail(), owner.getLastName());
236	        for (Owner existing : this.clinicService.findAllOwners()) {
237	            if (existing.isDeleted()) {
238	                continue;
239	            }
240	            if (identityKey.equals(OwnerIdentity.identityKey(toE164(existing.getTelephone()),
241	                existing.getEmail(), existing.getLastName()))) {
242	                return new ResponseEntity<>(HttpStatus.CONFLICT);
243	            }
244	        }
245	        // Soft-match: the owner is not a hard (identityKey) duplicate, but if it shares an
246	        // existing owner's last name and postcode while having a different normalized
247	        // telephone it is still created and flagged as a possible duplicate of that owner. A
248	        // declared household member, however, is not a suspected duplicate, so it is never flagged.
249	        if (declaredHouseholdMember) {
250	            owner.setPossibleDuplicate(false);
251	        }
252	        else {
253	            applyPossibleDuplicate(owner);
254	        }
255	        owner.setMemberId(deduplicatedMemberId(memberId(
256	            owner.getPostcode(), owner.getTelephone(), owner.getLastName(), owner.getRegistrationDate())));
257	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
258	        this.clinicService.saveOwner(owner);
259	        if (idempotencyKey != null) {
260	            idempotentCreates.put(idempotencyKey, owner.getId());
261	        }
262	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
263	        Map<String, Integer> householdSizes = householdSizes();
264	        applyMembership(ownerDto, owner, householdSizes);
265	        capMembershipLevelToHousehold(ownerDto, owner, householdSizes);
266	        applyOwnerSegment(ownerDto);
267	        AUDIT.info("owner created: id={} memberId={} registrationDate={} membershipLevel={}",
268	            owner.getId(), owner.getMemberId(), owner.getRegistrationDate(),
269	            ownerDto.getMembershipLevel());
270	        emitOwnerCreatedEvent(owner.getId(), primaryIdentifier(owner), ownerDto.getMembershipLevel());
271	        NOTIFY.info("welcome: ownerId={} memberId={}", owner.getId(), owner.getMemberId());
272	        ownerDto.setBulkSignupWarning(isBulkSignupDay());
273	        ownerDto.setCapacityWarning(isApproachingCapacity(owner.getCity()));
274	        headers.setLocation(UriComponentsBuilder.newInstance()
275	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
276	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
277	    }
278	
279	    /**
280	     * The owner's current primary identifier, as carried by the structured {@code OWNER_CREATED}
281	     * event. This is the owner's unified {@link Owner#getMemberId() memberId}.
282	     *
283	     * @param owner the newly created, saved owner
284	     * @return the owner's current primary identifier
285	     */
286	    private static String primaryIdentifier(Owner owner) {
287	        return owner.getMemberId();
288	    }
289	
290	    /**
291	     * Emits the immutable, structured {@code OWNER_CREATED} audit event via the {@code AUDIT}
292	     * logger, in addition to the human-readable audit line. The event is a JSON object
293	     * {@code {seq, ownerId, memberId, membershipLevel, event:'OWNER_CREATED'}} where {@code seq}
294	     * is a process-wide monotonically increasing integer across creates, and the {@code memberId}
295	     * slot carries the owner's {@link #primaryIdentifier current primary identifier}.
296	     *
297	     * @param ownerId         the newly created owner's id
298	     * @param primaryId       the owner's current primary identifier (the memberId)
299	     * @param membershipLevel the owner's resolved membership level
300	     */
301	    private static void emitOwnerCreatedEvent(int ownerId, String primaryId, int membershipLevel) {
302	        long seq = AUDIT_EVENT_SEQ.incrementAndGet();
303	        AUDIT.info("{\"seq\":{},\"ownerId\":{},\"memberId\":\"{}\",\"membershipLevel\":{},"
304	            + "\"event\":\"OWNER_CREATED\"}", seq, ownerId, primaryId, membershipLevel);
305	    }
306	
307	    /**
308	     * Reads the {@code Idempotency-Key} header of the request currently being handled, used to make
309	     * owner creation idempotent. Returns the trimmed key when present and non-blank, otherwise
310	     * {@code null} (including when there is no active servlet request), so a missing or blank key
311	     * simply means "no idempotency" and the create proceeds normally.
312	     *
313	     * @return the current request's idempotency key, or {@code null} when none is supplied
314	     */
315	    private static String currentIdempotencyKey() {
316	        RequestAttributes attributes = RequestContextHolder.getRequestAttributes();
317	        if (!(attributes instanceof ServletRequestAttributes servletAttributes)) {
318	            return null;
319	        }
320	        String key = servletAttributes.getRequest().getHeader(IDEMPOTENCY_KEY_HEADER);
321	        if (key == null || key.isBlank()) {
322	            return null;
323	        }
324	        return key.trim();
325	    }
326	
327	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
328	    @Override
329	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
330	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
331	        if (currentOwner == null) {
332	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
