423	    /**
424	     * The maximum number of owners permitted per city. Owner creation is rejected once the
425	     * owner's city already contains this many owners.
426	     */
427	    private static final int MAX_OWNERS_PER_CITY = 50;
428	
429	    /**
430	     * Counts how many existing owners live in the given city, compared case-insensitively.
431	     * This is evaluated before the new owner is persisted, so the owner being created is not
432	     * included in the count.
433	     *
434	     * @param city the new owner's city
435	     * @return the number of existing owners in that city
436	     */
437	    private int countOwnersInCity(String city) {
438	        int count = 0;
439	        for (Owner existing : this.clinicService.findAllOwners()) {
440	            if (city.equalsIgnoreCase(existing.getCity())) {
441	                count++;
442	            }
443	        }
444	        return count;
445	    }
