447	    /**
448	     * The number of owners in a city at or above which a capacity warning is raised. Once the
449	     * owner's city holds at least this many owners (but is still below {@link #MAX_OWNERS_PER_CITY},
450	     * the hard limit), the city is approaching capacity and {@code capacityWarning} is reported as
451	     * {@code true} in the owner response.
452	     */
453	    private static final int CAPACITY_WARNING_THRESHOLD = 40;
454	
455	    /**
456	     * Reports whether the given city is approaching the per-city capacity limit, i.e. whether it
457	     * already holds between {@link #CAPACITY_WARNING_THRESHOLD} (40) and
458	     * {@link #MAX_OWNERS_PER_CITY} minus one (49) owners inclusive. At the hard limit of 50 the
459	     * create is rejected outright, so a full city never warns.
460	     *
461	     * @param city the owner's city
462	     * @return {@code true} when the city holds 40-49 owners, otherwise {@code false}
463	     */
464	    private boolean isApproachingCapacity(String city) {
465	        int count = countOwnersInCity(city);
466	        return count >= CAPACITY_WARNING_THRESHOLD && count < MAX_OWNERS_PER_CITY;
467	    }
