469	    /**
470	     * The maximum number of owners that may be created in a single business day. Owner
471	     * creation is rejected once this many owners already fall on the new owner's adjusted
472	     * business day {@code registrationDate}.
473	     */
474	    private static final int MAX_OWNERS_PER_DAY = 100;
475	
476	    /**
477	     * The fixed list of public holidays that the business-day roll skips over. A date that
478	     * lands on one of these is rolled forward to the next non-holiday business day.
479	     */
480	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
481	        LocalDate.parse("2026-01-01"), LocalDate.parse("2026-01-26"),
482	        LocalDate.parse("2026-04-25"), LocalDate.parse("2026-12-25"),
483	        LocalDate.parse("2026-12-28"));
484	
485	    /**
486	     * Rolls a date forward to the next business day: a Saturday, Sunday or listed public
487	     * holiday is moved forward one day at a time until a non-holiday weekday is reached,
488	     * while a date that is already a non-holiday weekday is returned unchanged.
489	     *
490	     * @param date the date to adjust
491	     * @return the same date if it is a non-holiday weekday, otherwise the next such day
492	     */
493	    private LocalDate toBusinessDay(LocalDate date) {
494	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY || date.getDayOfWeek() == DayOfWeek.SUNDAY
495	                || PUBLIC_HOLIDAYS.contains(date)) {
496	            date = date.plusDays(1);
497	        }
498	        return date;
499	    }
