501	    /**
502	     * Counts how many existing owners fall on the given business day, i.e. whose {@code
503	     * registrationDate} rolls forward to the same business day. This is evaluated before the
504	     * new owner is persisted, so the owner being created is not included in the count.
505	     *
506	     * @param businessDay the adjusted business day to count against
507	     * @return the number of existing owners registered on that business day
508	     */
509	    private int countOwnersRegisteredOn(LocalDate businessDay) {
510	        int count = 0;
511	        for (Owner existing : this.clinicService.findAllOwners()) {
512	            LocalDate existingDate = existing.getRegistrationDate();
513	            if (existingDate != null && businessDay.equals(toBusinessDay(existingDate))) {
514	                count++;
515	            }
516	        }
517	        return count;
518	    }
