538	    /**
539	     * Builds the unified member id for a newly created owner, formatted
540	     * {@code '<REGION><FY><HASH8><CHK>'} where {@code REGION} is the canonical region
541	     * {@link OwnerLocality#forPostcodeOrUnknown derived from the postcode} (or
542	     * {@code "UNKNOWN"} when the postcode resolves no region), {@code FY} is the last two
543	     * digits of the fiscal year of the business-day-adjusted registration date (fiscal year
544	     * starts 1 July, named by the year it ends in), {@code HASH8} is the first eight
545	     * upper-case hex characters of the SHA-256 digest of {@code normalizedTelephone + lastName}
546	     * (the same hash used by the region-and-hash identity), and {@code CHK} is a single Luhn
547	     * check digit computed over the digits of {@code '<REGION><FY><HASH8>'}. The id carries no
548	     * sequence number, so it is stable for a given telephone, last name and fiscal year rather
549	     * than dependent on creation order.
550	     *
551	     * @param postcode            the owner's postcode (may be {@code null})
552	     * @param normalizedTelephone the owner's normalized E.164 telephone
553	     * @param lastName            the owner's last name
554	     * @param registrationDate    the owner's business-day-adjusted registration date
555	     * @return the assigned member id (e.g. {@code 'NSW271A2B3C4D5'})
556	     */
557	    private static String memberId(String postcode, String normalizedTelephone, String lastName,
558	        LocalDate registrationDate) {
559	        String region = org.springframework.samples.petclinic.mapper.OwnerLocality.forPostcodeOrUnknown(postcode);
560	        int fiscalYear = org.springframework.samples.petclinic.mapper.FiscalYear.yearValue(registrationDate);
561	        String fy = String.format("%02d", Math.floorMod(fiscalYear, 100));
562	        String base = region + fy + sha256Hex8(normalizedTelephone + lastName);
563	        int chk = org.springframework.samples.petclinic.mapper.OwnerLocality.luhn(base);
564	        return base + chk;
565	    }
566	
567	    /**
568	     * De-duplicates a freshly computed {@code base} member id against the ids already
569	     * assigned to existing owners. When {@code base} is free it is returned unchanged;
570	     * otherwise {@code '-<n>'} is appended with the smallest {@code n} of two or more that
571	     * yields an id no existing owner holds.
572	     *
573	     * @param base the computed {@code '<REGION><FY><HASH8><CHK>'} member id
574	     * @return {@code base}, or {@code base + "-<n>"} de-duplicated to be unique
575	     */
576	    private String deduplicatedMemberId(String base) {
577	        Set<String> existing = new HashSet<>();
578	        for (Owner owner : this.clinicService.findAllOwners()) {
579	            if (owner.getMemberId() != null) {
580	                existing.add(owner.getMemberId());
581	            }
582	        }
583	        if (!existing.contains(base)) {
584	            return base;
585	        }
586	        int n = 2;
587	        while (existing.contains(base + "-" + n)) {
588	            n++;
589	        }
590	        return base + "-" + n;
591	    }
592	
593	    /**
594	     * Returns the first eight upper-case hex characters of the SHA-256 digest of the UTF-8
595	     * bytes of {@code source} — the {@code HASH8} component of an owner's member id.
596	     *
597	     * @param source the string to hash
598	     * @return the first eight upper-case hex characters of {@code SHA-256(source)}
599	     */
600	    private static String sha256Hex8(String source) {
601	        try {
602	            byte[] digest = MessageDigest.getInstance("SHA-256")
603	                .digest(source.getBytes(StandardCharsets.UTF_8));
604	            StringBuilder hex = new StringBuilder(digest.length * 2);
605	            for (byte b : digest) {
606	                hex.append(String.format("%02x", b));
607	            }
608	            return hex.substring(0, 8).toUpperCase();
609	        } catch (NoSuchAlgorithmException e) {
610	            throw new IllegalStateException("SHA-256 not available", e);
611	        }
612	    }
