634	    /**
635	     * Canonical expansions applied to common street-type abbreviations during address
636	     * normalization. Keys and values are upper-cased so the lookup runs after the address
637	     * has itself been upper-cased.
638	     */
639	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
640	        "ST", "STREET",
641	        "RD", "ROAD",
642	        "AVE", "AVENUE");
643	
644	    /**
645	     * Normalizes an owner address for creation. Leading and trailing whitespace is trimmed,
646	     * every run of internal whitespace is collapsed to a single space, the result is
647	     * upper-cased and common street-type abbreviations are expanded ({@code ST -> STREET},
648	     * {@code RD -> ROAD}, {@code AVE -> AVENUE}). An abbreviation is recognized as a whole
649	     * token, optionally carrying a single trailing full stop (so both {@code 'St'} and
650	     * {@code 'St.'} become {@code 'STREET'}). The normalized value is what gets stored,
651	     * returned and compared for household duplicates; an address that is blank once
652	     * normalized fails the required-field check.
653	     *
654	     * @param address the raw address value supplied by the client
655	     * @return the normalized address (empty string when {@code address} is null or blank)
656	     */
657	    /**
658	     * Normalizes the address an owner supplies, preferring the structured form, and stores the
659	     * normalized structured lines on the owner. When a non-blank {@code addressLine1} is present
660	     * the structured fields are used: {@code addressLine1} (and {@code addressLine2}, when
661	     * present) are {@link #normalizeAddress normalized} and set on the owner, and the composed
662	     * address returned is the normalized {@code addressLine1} with a single space and the
663	     * normalized {@code addressLine2} appended when {@code addressLine2} is present. Otherwise
664	     * the flat {@code address} is normalized and returned, and the structured lines are left
665	     * unset. The returned value becomes the owner's stored {@code address}, read by everything
666	     * downstream (household hash, postcode validation and locality); an owner that supplies
667	     * neither form yields an empty string, failing the required-address check.
668	     *
669	     * @param owner          the owner being created, whose structured address lines are set here
670	     * @param ownerFieldsDto the submitted owner fields
671	     * @return the composed, normalized address (empty string when no address form is supplied)
672	     */
673	    private static String applyAddress(Owner owner, OwnerFieldsDto ownerFieldsDto) {
674	        String addressLine1 = ownerFieldsDto.getAddressLine1();
675	        if (addressLine1 != null && !addressLine1.isBlank()) {
676	            String normalizedLine1 = normalizeAddress(addressLine1);
677	            owner.setAddressLine1(normalizedLine1);
678	            String addressLine2 = ownerFieldsDto.getAddressLine2();
679	            if (addressLine2 != null && !addressLine2.isBlank()) {
680	                String normalizedLine2 = normalizeAddress(addressLine2);
681	                owner.setAddressLine2(normalizedLine2);
682	                return normalizedLine1 + " " + normalizedLine2;
683	            }
684	            owner.setAddressLine2(null);
685	            return normalizedLine1;
686	        }
687	        owner.setAddressLine1(null);
688	        owner.setAddressLine2(null);
689	        return normalizeAddress(ownerFieldsDto.getAddress());
690	    }
691	
692	    private static String normalizeAddress(String address) {
693	        if (address == null) {
694	            return "";
695	        }
696	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase();
697	        if (collapsed.isEmpty()) {
698	            return "";
699	        }
700	        StringBuilder normalized = new StringBuilder(collapsed.length());
701	        for (String token : collapsed.split(" ")) {
702	            String core = token.endsWith(".") ? token.substring(0, token.length() - 1) : token;
703	            String expanded = ADDRESS_ABBREVIATIONS.get(core);
704	            if (normalized.length() > 0) {
705	                normalized.append(' ');
706	            }
707	            normalized.append(expanded != null ? expanded : token);
708	        }
709	        return normalized.toString();
710	    }
711	
712	    /**
713	     * Normalizes a last name or address for household-duplicate comparison: leading and
714	     * trailing whitespace is trimmed, every run of internal whitespace is collapsed to a
715	     * single space and the result is lower-cased. Two owners are considered to share a
716	     * household when both their last names and addresses produce the same key.
717	     *
718	     * @param value the raw last name or address value
719	     * @return the normalized comparison key (empty string when {@code value} is null)
720	     */
721	    private static String householdKey(String value) {
722	        if (value == null) {
723	            return "";
724	        }
725	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
726	    }
727	
728	    /**
729	     * Derives the stable shared household identifier for the given normalized last name key
730	     * and postcode. The identifier is deterministic — the same household (same
731	     * {@link #householdKey normalized} last name and postcode) always maps to the same
732	     * value — so every owner in a household is assigned an identical id. It is the
733	     * upper-cased first twelve hex characters of the SHA-256 digest of {@code
734	     * '<lastNameKey>|<postcode>'}.
735	     *
736	     * @param lastNameKey the normalized last name key
737	     * @param postcode    the owner's postcode
738	     * @return the shared household identifier
739	     */
740	    private static String householdId(String lastNameKey, String postcode) {
741	        String source = lastNameKey + "|" + postcode;
742	        try {
743	            byte[] digest = MessageDigest.getInstance("SHA-256")
744	                .digest(source.getBytes(StandardCharsets.UTF_8));
745	            StringBuilder hex = new StringBuilder(digest.length * 2);
746	            for (byte b : digest) {
747	                hex.append(String.format("%02x", b));
748	            }
749	            return hex.substring(0, 12).toUpperCase();
750	        } catch (NoSuchAlgorithmException e) {
751	            throw new IllegalStateException("SHA-256 not available", e);
752	        }
753	    }
754	
755	    /**
756	     * Computes the deterministic {@link #householdId household id} an existing owner belongs to,
757	     * derived from its {@link #householdKey normalized} last name and its postcode. Returns
758	     * {@code null} when the owner has no postcode (such an owner has no household), so it never
759	     * collides with a computed household id.
760	     *
761	     * @param owner the existing owner
762	     * @return the owner's household id, or {@code null} when it has no postcode
763	     */
764	    private static String computeHouseholdId(Owner owner) {
765	        if (owner.getPostcode() == null) {
766	            return null;
767	        }
768	        return householdId(householdKey(owner.getLastName()), owner.getPostcode());
769	    }
770	
771	    /**
772	     * Populates an owner's {@code membershipPoints} and {@code membershipLevel} on the given
773	     * dto, sizing the owner's household from all owners so the household-of-three-or-more
774	     * factor is scored correctly. Use {@link #applyMembership(OwnerDto, Owner, Map)} instead
775	     * when mapping a collection to size every household from a single scan.
776	     *
777	     * @param ownerDto the dto to populate
778	     * @param owner    the owner being mapped
779	     */
780	    private void applyMembership(OwnerDto ownerDto, Owner owner) {
781	        applyMembership(ownerDto, owner, householdSizes());
782	    }
783	
784	    /**
785	     * Populates an owner's {@code membershipPoints} and {@code membershipLevel} on the given
786	     * dto using a pre-computed map of household id to member count.
787	     *
788	     * @param ownerDto       the dto to populate
789	     * @param owner          the owner being mapped
790	     * @param householdSizes household id to member count, as returned by {@link #householdSizes()}
791	     */
792	    private void applyMembership(OwnerDto ownerDto, Owner owner, Map<String, Integer> householdSizes) {
793	        int householdSize = owner.getHouseholdId() == null ? 1
794	            : householdSizes.getOrDefault(owner.getHouseholdId(), 1);
795	        int points = MembershipPoints.points(owner, householdSize);
796	        ownerDto.setMembershipPoints(points);
797	        ownerDto.setMembershipLevel(MembershipPoints.level(points));
798	        applyOwnerSegment(ownerDto);
799	    }
800	
801	    /**
802	     * Populates an owner's {@code ownerSegment} on the given dto from its already-applied
803	     * {@code membershipLevel} and mapped {@code locality}. Call this whenever the membership
804	     * level changes (e.g. after {@link #capMembershipLevelToHousehold}) so the segment stays
805	     * consistent with the level.
806	     *
807	     * @param ownerDto the dto whose membershipLevel and locality are already populated
808	     */
809	    private void applyOwnerSegment(OwnerDto ownerDto) {
810	        Integer membershipLevel = ownerDto.getMembershipLevel();
811	        int level = membershipLevel == null ? 1 : membershipLevel;
812	        ownerDto.setOwnerSegment(org.springframework.samples.petclinic.mapper.OwnerSegment.segment(
813	            level, ownerDto.getLocality()));
814	    }
815	
816	    /**
817	     * Caps a newly created owner's {@code membershipLevel} at one above the highest
818	     * {@code membershipLevel} among the other current members of its household, writing the
819	     * capped value back onto the dto and returning it. A member's current level is scored the
820	     * same way as {@link #applyMembership}, using {@code householdSizes} so the
821	     * household-of-three-or-more factor reflects the household as it now stands. When the owner
822	     * has no household, or is the only member of its household, no cap applies and the level is
823	     * returned unchanged.
824	     *
825	     * @param ownerDto       the newly created owner's dto, with its uncapped membership already applied
826	     * @param owner          the newly created owner (already saved, so it has an id)
827	     * @param householdSizes household id to member count, as returned by {@link #householdSizes()}
828	     * @return the resulting (possibly capped) membership level
829	     */
830	    private int capMembershipLevelToHousehold(OwnerDto ownerDto, Owner owner,
831	        Map<String, Integer> householdSizes) {
832	        int level = ownerDto.getMembershipLevel();
833	        String householdId = owner.getHouseholdId();
834	        if (householdId == null) {
835	            return level;
836	        }
837	        Integer maxMemberLevel = null;
838	        for (Owner existing : this.clinicService.findAllOwners()) {
839	            if (existing.isDeleted() || existing.getId().equals(owner.getId())) {
840	                continue;
841	            }
842	            if (householdId.equals(existing.getHouseholdId())) {
843	                int size = householdSizes.getOrDefault(householdId, 1);
844	                int memberLevel = MembershipPoints.level(MembershipPoints.points(existing, size));
845	                maxMemberLevel = maxMemberLevel == null ? memberLevel
846	                    : Math.max(maxMemberLevel, memberLevel);
847	            }
848	        }
849	        if (maxMemberLevel != null && level > maxMemberLevel + 1) {
850	            level = maxMemberLevel + 1;
851	            ownerDto.setMembershipLevel(level);
852	        }
853	        return level;
854	    }
855	
856	    /**
857	     * Counts how many owners belong to each household, keyed by household id. Owners without a
858	     * household id (no postcode) are excluded — such an owner is its own single-member household.
859	     *
860	     * @return a map from household id to the number of owners sharing it
861	     */
862	    private Map<String, Integer> householdSizes() {
863	        Map<String, Integer> sizes = new java.util.HashMap<>();
864	        for (Owner existing : this.clinicService.findAllOwners()) {
865	            String householdId = existing.getHouseholdId();
866	            if (householdId != null) {
867	                sizes.merge(householdId, 1, Integer::sum);
868	            }
869	        }
870	        return sizes;
871	    }
872	
873	    /**
874	     * Applies soft-match (possible-duplicate) detection to a new owner that has already
875	     * cleared hard {@code identityKey} duplicate rejection. The owner is flagged as a
876	     * possible duplicate when a non-deleted existing owner shares its {@link
877	     * OwnerIdentity#soundex soundex(lastName)} and its postcode while producing a different
878	     * {@code identityKey}; {@code possibleDuplicateOf} is then set to that existing owner's id.
879	     * Because the telephone is part of the identity key, two owners with the same last name and
880	     * postcode but different telephones differ in their keys and so surface here as a soft match
881	     * rather than a hard duplicate. When several existing owners match, the one with the lowest
882	     * id is chosen so the result is deterministic. When no such owner exists — or the new owner
883	     * has no postcode to compare — {@code possibleDuplicate} is set to {@code false} and no
884	     * matching id is recorded.
885	     *
886	     * @param owner the new owner, already normalized (E.164 telephone, validated postcode)
887	     */
888	    private void applyPossibleDuplicate(Owner owner) {
889	        owner.setPossibleDuplicate(false);
890	        if (owner.getPostcode() == null) {
891	            return;
892	        }
893	        String soundex = OwnerIdentity.soundex(owner.getLastName());
894	        String identityKey = OwnerIdentity.identityKey(owner.getTelephone(), owner.getEmail(), owner.getLastName());
895	        Owner match = null;
896	        for (Owner existing : this.clinicService.findAllOwners()) {
897	            if (existing.isDeleted()) {
898	                continue;
899	            }
900	            if (soundex.equals(OwnerIdentity.soundex(existing.getLastName()))
901	                && owner.getPostcode().equals(existing.getPostcode())
902	                && !identityKey.equals(OwnerIdentity.identityKey(toE164(existing.getTelephone()),
903	                    existing.getEmail(), existing.getLastName()))) {
904	                if (match == null || (existing.getId() != null
905	                    && existing.getId() < match.getId())) {
906	                    match = existing;
907	                }
908	            }
909	        }
910	        if (match != null) {
911	            owner.setPossibleDuplicate(true);
912	            owner.setPossibleDuplicateOf(match.getId());
913	        }
914	    }
915	
916	    /**
917	     * Normalizes a telephone number for owner creation into E.164 form. Spaces, dashes
918	     * and brackets are stripped. When the number already carries a leading {@code '+'}
919	     * and country code these are kept; a number written in national trunk form (a leading
920	     * {@code '0'}) is treated as Australian, so the {@code '0'} is dropped and country code
921	     * {@code '+61'} prepended; any other bare number is treated as a NANP number and country
922	     * code {@code '+1'} is prepended. The resulting number must have between 8 and 15 digits
923	     * after the {@code '+'}, and its national-number length must be valid for the detected
924	     * country code (see {@link #hasValidNationalLength}).
925	     *
926	     * @param telephone the raw telephone value supplied by the client
927	     * @return the E.164 telephone (e.g. {@code +61412345678}), or {@code null} when it
928	     *         cannot form a valid E.164 number (signalling a 400 Bad Request)
929	     */
930	    private static String toE164(String telephone) {
931	        if (telephone == null) {
932	            return null;
933	        }
934	        String cleaned = telephone.replaceAll("[\\s\\-()]", "");
935	        String digits;
936	        if (cleaned.startsWith("+")) {
937	            digits = cleaned.substring(1);
938	        } else if (cleaned.startsWith("0")) {
939	            digits = "61" + cleaned.substring(1);
940	        } else {
941	            digits = "1" + cleaned;
942	        }
943	        if (!digits.matches("[0-9]{8,15}")) {
944	            return null;
945	        }
946	        if (!hasValidNationalLength(digits)) {
947	            return null;
948	        }
949	        return "+" + digits;
950	    }
951	
952	    /**
953	     * Validates the national-number length of an E.164 digit string against its country
954	     * code: Australia ({@code +61}) requires exactly 9 national digits and the NANP
955	     * ({@code +1}) requires exactly 10. Numbers under any other country code are not
956	     * length-checked here — only the general 8-to-15-digit E.164 bound applies to them.
957	     *
958	     * @param digits the E.164 digits (without the leading {@code '+'})
959	     * @return {@code true} when the national-number length is valid for the country code
960	     */
961	    private static boolean hasValidNationalLength(String digits) {
962	        if (digits.startsWith("61")) {
963	            return digits.length() - 2 == 9;
964	        }
965	        if (digits.startsWith("1")) {
966	            return digits.length() - 1 == 10;
967	        }
968	        return true;
969	    }
970	
971	    /**
972	     * Inclusive 4-digit postcode ranges permitted for each canonical region: NSW 2000-2099,
973	     * VIC 3000-3099 and QLD 4000-4099. A region absent from this table (e.g. the {@code
974	     * "UNKNOWN"} derived for a city with no known region) imposes no range restriction.
975	     */
976	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
977	        "NSW", new int[] {2000, 2099},
978	        "VIC", new int[] {3000, 3099},
979	        "QLD", new int[] {4000, 4099});
980	
981	    /**
982	     * Validates an owner's postcode for creation. A postcode is only ever validated when
983	     * present (an absent postcode is optional and accepted). When present it must be exactly
984	     * four digits and, for a city whose {@link OwnerLocality#forCity region} has a known
985	     * postcode range, must fall inside that inclusive range (NSW 2000-2099, VIC 3000-3099,
986	     * QLD 4000-4099). A city with no known region accepts any 4-digit postcode.
987	     *
988	     * @param postcode the supplied postcode (never {@code null} here)
989	     * @param city     the owner's city, used to derive the region
990	     * @return {@code true} when the postcode is valid for the city, {@code false} otherwise
991	     *         (signalling a 400 Bad Request)
992	     */
993	    private static boolean isValidPostcode(String postcode, String city) {
994	        if (!postcode.matches("[0-9]{4}")) {
995	            return false;
996	        }
997	        int[] range = REGION_POSTCODES.get(
998	            org.springframework.samples.petclinic.mapper.OwnerLocality.forCity(city));
999	        if (range == null) {
1000	            return true;
1001	        }
1002	        int value = Integer.parseInt(postcode);
1003	        return value >= range[0] && value <= range[1];
1004	    }
1005	
1006	    /**
1007	     * Disposable email domains that are not accepted for owner creation. An owner whose
1008	     * email domain (compared case-insensitively) is in this set is rejected with a 400
1009	     * Bad Request.
1010	     */
1011	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS = Set.of(
1012	        "mailinator.com", "tempmail.com", "guerrillamail.com");
1013	
1014	    /**
1015	     * Normalizes an owner email for creation. A present email must be a syntactically
1016	     * valid address whose domain is not on the disposable-domain blocklist ({@link
1017	     * #DISPOSABLE_EMAIL_DOMAINS}); the returned value is lower-cased.
1018	     *
1019	     * @param email the raw email value supplied by the client (never {@code null} here)
1020	     * @return the lower-cased email, or {@code null} when it is not a syntactically valid
1021	     *         address or its domain is a disposable domain (signalling a 400 Bad Request)
1022	     */
1023	    private static String normalizeEmail(String email) {
1024	        String trimmed = email.trim();
1025	        if (!trimmed.matches("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$")) {
1026	            return null;
1027	        }
1028	        String normalized = trimmed.toLowerCase();
1029	        String domain = normalized.substring(normalized.indexOf('@') + 1);
1030	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
1031	            return null;
1032	        }
1033	        return normalized;
1034	    }
1035	}
